def tiled_conv(img, mask, tile):
    """convTiled on the CPU, standard library only. img is a list of H rows of W numbers, mask a K x K list
    (K odd), tile the output tile width. Each block loads a (tile + K - 1)^2 input tile with zero padding,
    then its inner tile x tile threads compute one output each. Returns the H x W output."""
    h, w, k = len(img), len(img[0]), len(mask)
    r, blk = k // 2, tile + k - 1
    out = [[0.0] * w for _ in range(h)]
    for by in range((h + blk - 1) // blk):
        for bx in range((w + blk - 1) // blk):
            s = [[0.0] * blk for _ in range(blk)]
            for ty in range(blk):                          # every thread loads one pixel
                for tx in range(blk):
                    row, col = by * blk + ty - r, bx * blk + tx - r
                    if 0 <= row < h and 0 <= col < w:
                        s[ty][tx] = img[row][col]
            for ty in range(r, blk - r):                   # inner threads only
                for tx in range(r, blk - r):
                    orow, ocol = by * blk + ty - r, bx * blk + tx - r
                    if orow < h and ocol < w:
                        out[orow][ocol] = sum(s[ty + i - r][tx + j - r] * mask[i][j]
                                              for i in range(k) for j in range(k))
    return out

